const jobs = $input.all().map(i => i.json).filter(j => j.title);
const today = new Date().toISOString().slice(0, 10);

let html;
if (jobs.length === 0) {
  html = "<p>No strong matches today. Check again tomorrow.</p>";
} else {
  html = "<h2>Today's top job matches</h2><ol>" + jobs.map(j =>
    `<li style="margin-bottom:14px"><b>${j.title}</b> at ${j.company || "Unknown company"}<br>` +
    `<b>Fit score: ${j.score}</b> | ${j.reason}<br>` +
    `Location: ${j.location || "Not listed, check the posting"} | Source: ${j.source} | Posted: ${j.date}<br>` +
    `<a href="${j.url}">View and apply</a></li>`
  ).join("") + "</ol>";
}

return [{ json: { subject: `Job matches for ${today} (${jobs.length} strong)`, html } }];

const jobs = $input.first().json.jobs || [];
return jobs.map(j => ({
  json: {
    title: j.title,
    company: j.company_name,
    location: j.candidate_required_location || "",
    url: j.url,
    date: (j.publication_date || "").slice(0, 10),
    description: (j.description || "").replace(/<[^>]+>/g, " ").slice(0, 1500),
    source: "Remotive"
  }
}));

const titleWords = ["data analyst", "business analyst", "bi analyst",
  "business intelligence", "power bi", "reporting analyst", "analyst", "data",
  "reporting", "bi developer", "analytics", "supply chain analyst",
  "logistics analyst", "marketing analyst", "product analyst",
  "automation specialist", "insights analyst", "operations analyst", "sales analyst"];

const goodLocations = ["worldwide", "anywhere", "africa", "nigeria", "lagos",
  "emea", "global", "international", "work from anywhere"];

// whole-word matches only, so "lead" won't block "lead generation"
const badWords = ["senior", "sr", "lead", "principal", "staff", "manager",
  "director", "head of", "owner", "security", "crypto", "digital assets", "engineer"];
const badRegex = new RegExp("\\b(" + badWords.join("|").replace(/\./g, "\\.") + ")\\b", "i");

const maxAgeDays = 7;
const cutoff = Date.now() - maxAgeDays * 24 * 60 * 60 * 1000;
const seen = new Set();

return $input.all().filter(item => {
  const title = (item.json.title || "").toLowerCase();
  const loc = (item.json.location || "").toLowerCase().trim();
  const url = item.json.url;
  if (!url || seen.has(url)) return false;
  seen.add(url);

  const posted = Date.parse(item.json.date);
  const recent = isNaN(posted) || posted >= cutoff;   // keep jobs with no date

  const titleOk = titleWords.some(w => title.includes(w));
  const notExcluded = !badRegex.test(title);

  const locationOk = loc === "" || loc === "remote" ||
    goodLocations.some(w => loc.includes(w));

  return recent && titleOk && notExcluded && locationOk;
});

return $input.all()
  .map(i => i.json)
  .filter(j => j.position)
  .map(j => ({
    json: {
      title: j.position,
      company: j.company,
      location: j.location || "",
      url: j.url,
      date: (j.date || "").slice(0, 10),
      description: (j.description || "").replace(/<[^>]+>/g, " ").slice(0, 1500),
      source: "RemoteOK"
    }
  }));

return $input.all().map(i => i.json).map(j => {
  const parts = (j.title || "").split(":");
  const company = parts.length > 1 ? parts.shift().trim() : "";
  return {
    json: {
      title: parts.join(":").trim(),
      company,
      location: "",
      url: j.link,
      date: (j.isoDate || j.pubDate || "").slice(0, 10),
      description: (j.contentSnippet || j.content || "").replace(/<[^>]+>/g, " ").slice(0, 1500),
      source: "We Work Remotely"
    }
  };
});

