const MIN_SCORE = 55;   // change this number to adjust how strict matches are

const jobs = $('Skip Seen Jobs').all();
const results = $input.all();
const out = [];

results.forEach((r, i) => {
  const job = jobs[i] ? jobs[i].json : null;
  if (!job || !job.title) return;

  if (r.json.error) {
    out.push({ json: { ...job, score: "Not scored", reason: "AI scoring failed, check manually" } });
    return;
  }

  let parsed = { score: 0, reason: "", location_ok: false };
  try {
    const text = r.json.choices[0].message.content.replace(/```json|```/g, "").trim();
    parsed = JSON.parse(text);
  } catch (e) {
    out.push({ json: { ...job, score: "Not scored", reason: "Could not read AI reply, check manually" } });
    return;
  }

  const score = Number(parsed.score) || 0;
  if (score >= MIN_SCORE && parsed.location_ok !== false) {
    out.push({ json: { ...job, score: score, reason: parsed.reason } });
  }
});

return out.sort((a, b) => (Number(b.json.score) || 0) - (Number(a.json.score) || 0));

const jobs = $input.first().json.jobs || [];
