const jobs = $input.first().json.jobs || [];
const strip = h => (h || "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim().slice(0, 1500);
return jobs.map(j => {
  const raw = j.pubDate;
  const ms = typeof raw === "number" ? (raw < 1e12 ? raw * 1000 : raw) : Date.parse(raw);
  const locs = (j.locationRestrictions || []).map(l => l.name).join(", ");
  return { json: {
    title: j.title,
    company: j.companyName,
    location: locs || "worldwide",
    url: j.applicationLink,
    date: isNaN(ms) ? "" : new Date(ms).toISOString(),
    description: strip(j.description || j.excerpt),
    source: "Himalayas"
  }};
});
